with base as (select *, round(price / cost, 2) margin from products where launch_date > date '2023-12-06') select case when price >= 980 then 'PREMIUM' else 'STANDARD' end as price_tier, sum(price) filter (where category = 'Grocery') as grocery_total_price, count_if(category = 'Books') as books_events, count(*) as row_count from base group by cube (case when price >= 980 then 'PREMIUM' else 'STANDARD' end) order by price_tier nulls last
